) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `payment_audit_log` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `payment_id` int(11) NOT NULL,
  `user_id` int(11) NOT NULL,
  `action` varchar(50) NOT NULL,
  `field_changed` varchar(50) DEFAULT NULL,
  `old_value` text DEFAULT NULL,
  `new_value` text DEFAULT NULL,
  `note` varchar(500) DEFAULT NULL,
  `created_at` datetime DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `idx_audit_payment` (`payment_id`),
  KEY `idx_audit_user` (`user_id`),
  KEY `idx_audit_created` (`created_at`),
  CONSTRAINT `payment_audit_log_ibfk_1` FOREIGN KEY (`payment_id`) REFERENCES `payments` (`id`) ON DELETE CASCADE,
  CONSTRAINT `payment_audit_log_ibfk_2` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `payment_channels` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `title` varchar(100) NOT NULL,
  `channel_type` varchar(50) NOT NULL,
  `is_active` tinyint(1) NOT NULL DEFAULT 1,
  `sort_order` int(11) NOT NULL DEFAULT 0,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `payment_service_ticks` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `payment_id` int(11) NOT NULL,
  `item_key` varchar(50) NOT NULL,
  `item_label` varchar(150) DEFAULT NULL,
  `is_done` tinyint(1) NOT NULL DEFAULT 0,
  `done_reason` varchar(255) DEFAULT NULL,
  `ticked_by` int(11) DEFAULT NULL,
  `ticked_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_pay_tick` (`payment_id`,`item_key`),
  KEY `ticked_by` (`ticked_by`),
  KEY `idx_pay_ticks_payment` (`payment_id`),
  CONSTRAINT `payment_service_ticks_ibfk_1` FOREIGN KEY (`payment_id`) REFERENCES `payments` (`id`) ON DELETE CASCADE,
  CONSTRAINT `payment_service_ticks_ibfk_2` FOREIGN KEY (`ticked_by`) REFERENCES `users` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `payments` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `applicant_id` int(11) NOT NULL,
  `user_account_id` int(11) DEFAULT NULL,
  `payment_channel_id` int(11) DEFAULT NULL,
  `purpose` varchar(64) NOT NULL DEFAULT 'هزینهٔ ثبت‌نام',
  `amount` bigint(20) unsigned NOT NULL DEFAULT 0,
  `original_amount` bigint(20) unsigned DEFAULT NULL,
  `final_amount` bigint(20) unsigned DEFAULT NULL,
  `discount_reason` varchar(500) DEFAULT NULL,
  `fee_group_id` int(11) DEFAULT NULL,
  `is_rural_exempt` tinyint(1) NOT NULL DEFAULT 0,
  `fallback_used` tinyint(1) NOT NULL DEFAULT 0,
  `suspicion_flags` varchar(255) DEFAULT NULL,
  `reference_code` varchar(50) DEFAULT NULL,
  `description` varchar(500) DEFAULT NULL,
  `paid_at` date DEFAULT NULL,
  `receipt_document_id` int(11) DEFAULT NULL,
  `linked_request_id` int(11) DEFAULT NULL,
  `status` varchar(32) NOT NULL DEFAULT 'در انتظار رسید',
  `reviewed_by` int(11) DEFAULT NULL,
  `reviewed_at` datetime DEFAULT NULL,
  `reject_reason` varchar(255) DEFAULT NULL,
  `created_at` datetime DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `payment_channel_id` (`payment_channel_id`),
  KEY `receipt_document_id` (`receipt_document_id`),
  KEY `linked_request_id` (`linked_request_id`),
  KEY `reviewed_by` (`reviewed_by`),
  KEY `idx_pay_status` (`status`),
  KEY `idx_pay_applicant` (`applicant_id`),
  KEY `idx_pay_purpose` (`purpose`),
  KEY `idx_pay_user` (`user_account_id`),
  KEY `idx_pay_group` (`fee_group_id`),
  KEY `idx_pay_suspicion` (`suspicion_flags`(50)),
  CONSTRAINT `payments_ibfk_1` FOREIGN KEY (`applicant_id`) REFERENCES `applicants` (`id`) ON DELETE CASCADE,
  CONSTRAINT `payments_ibfk_2` FOREIGN KEY (`user_account_id`) REFERENCES `user_accounts` (`id`) ON DELETE SET NULL,
  CONSTRAINT `payments_ibfk_3` FOREIGN KEY (`payment_channel_id`) REFERENCES `payment_channels` (`id`) ON DELETE SET NULL,
  CONSTRAINT `payments_ibfk_4` FOREIGN KEY (`receipt_document_id`) REFERENCES `documents` (`id`) ON DELETE SET NULL,
  CONSTRAINT `payments_ibfk_5` FOREIGN KEY (`linked_request_id`) REFERENCES `license_access_requests` (`id`) ON DELETE SET NULL,
  CONSTRAINT `payments_ibfk_6` FOREIGN KEY (`reviewed_by`) REFERENCES `users` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `persian_date_cache` (
  `cache_key` varchar(64) NOT NULL,
  `gregorian_value` date NOT NULL,
  `persian_value` varchar(10) NOT NULL,
  `cached_at` datetime DEFAULT current_timestamp(),
  PRIMARY KEY (`cache_key`),
  KEY `idx_persian_date_gregorian` (`gregorian_value`),
  KEY `idx_persian_date_persian` (`persian_value`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `persons` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `national_code` char(10) NOT NULL,
  `first_name` varchar(50) NOT NULL,
  `last_name` varchar(50) NOT NULL,
  `father_name` varchar(50) DEFAULT NULL,
  `birth_date` date DEFAULT NULL,
  `mobile` char(11) NOT NULL,
  `mobile_2` char(11) DEFAULT NULL,
  `mobile_3` char(11) DEFAULT NULL,
  `postal_code` char(10) DEFAULT NULL,
  `person_type` enum('حقیقی','حقوقی') NOT NULL DEFAULT 'حقیقی',
  `company_name` varchar(150) DEFAULT NULL,
  `company_national_id` char(11) DEFAULT NULL,
  `reg_number` varchar(30) DEFAULT NULL,
  `reg_date` date DEFAULT NULL,
  `company_type` varchar(60) DEFAULT NULL,
  `economic_code` varchar(20) DEFAULT NULL,
  `created_at` datetime DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `national_code` (`national_code`),
  KEY `idx_person_mobile` (`mobile`),
  KEY `idx_person_mobile_2` (`mobile_2`),
  KEY `idx_person_mobile_3` (`mobile_3`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `postal_code_changes` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `applicant_id` int(11) NOT NULL,
  `old_postal_code` char(10) NOT NULL,
  `new_postal_code` char(10) NOT NULL,
  `status` varchar(32) NOT NULL DEFAULT 'در انتظار',
  `reviewed_by` int(11) DEFAULT NULL,
  `reviewed_at` datetime DEFAULT NULL,
  `reject_reason` varchar(255) DEFAULT NULL,
  `requested_at` datetime DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `reviewed_by` (`reviewed_by`),
  KEY `idx_applicant_postal` (`applicant_id`),
  KEY `idx_postal_status` (`status`),
  CONSTRAINT `postal_code_changes_ibfk_1` FOREIGN KEY (`applicant_id`) REFERENCES `applicants` (`id`) ON DELETE CASCADE,
  CONSTRAINT `postal_code_changes_ibfk_2` FOREIGN KEY (`reviewed_by`) REFERENCES `users` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `property_details` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `applicant_id` int(11) NOT NULL,
  `ownership_status` enum('شخص','مستأجر','سرپرست') NOT NULL,
  `province` varchar(50) NOT NULL,
  `county` varchar(50) NOT NULL,
  `township` varchar(50) DEFAULT NULL,
  `city` varchar(50) NOT NULL,
  `district` varchar(50) DEFAULT NULL,
  `rural_district` varchar(50) DEFAULT NULL,
  `village` varchar(50) DEFAULT NULL,
  `electricity_bill_id` varchar(20) NOT NULL,
  `address_street` varchar(100) DEFAULT NULL,
  `address_alley` varchar(100) DEFAULT NULL,
  `address_plaque` varchar(20) DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `idx_applicant_property` (`applicant_id`),
  CONSTRAINT `property_details_ibfk_1` FOREIGN KEY (`applicant_id`) REFERENCES `applicants` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `rate_limit_buckets` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `bucket_key` varchar(64) NOT NULL,
  `ip` varchar(45) NOT NULL,
  `hits_json` text NOT NULL DEFAULT '[]',
  `created_at` datetime DEFAULT current_timestamp(),
  `updated_at` datetime DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_rate_bucket` (`bucket_key`,`ip`),
  KEY `idx_rate_updated` (`updated_at`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `service_types` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `title` varchar(120) NOT NULL,
  `authority` varchar(150) DEFAULT NULL,
  `description` text DEFAULT NULL,
  `is_active` tinyint(1) NOT NULL DEFAULT 1,
  `sort_order` int(11) NOT NULL DEFAULT 0,
  `created_at` datetime DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `title` (`title`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `sessions` (
  `id` varchar(128) NOT NULL,
  `payload` text NOT NULL,
  `last_activity` int(11) NOT NULL,
  `user_id` int(11) DEFAULT NULL,
  `ip` varchar(45) DEFAULT NULL,
  `user_agent` varchar(255) DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_sessions_last_activity` (`last_activity`),
  KEY `idx_sessions_user` (`user_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `settings` (
  `setting_key` varchar(64) NOT NULL,
  `setting_value` text DEFAULT NULL,
  `updated_at` datetime DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`setting_key`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `sms_templates` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `title` varchar(100) NOT NULL,
  `sample_text` text DEFAULT NULL,
  `target_status` varchar(100) DEFAULT NULL,
  `is_active` tinyint(1) NOT NULL DEFAULT 1,
  `created_at` datetime DEFAULT current_timestamp(),
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `status_log` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `applicant_id` int(11) NOT NULL,
  `status_name` varchar(100) NOT NULL,
  `description` text DEFAULT NULL,
  `triggered_by` varchar(32) NOT NULL DEFAULT 'admin',
  `created_at` datetime DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `idx_applicant_log` (`applicant_id`),
  KEY `idx_status_log_created` (`created_at`),
  KEY `idx_status_log_triggered` (`triggered_by`,`created_at`),
  CONSTRAINT `status_log_ibfk_1` FOREIGN KEY (`applicant_id`) REFERENCES `applicants` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `sync_audit_log` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `applicant_id` int(11) DEFAULT NULL,
  `national_request_number` varchar(64) DEFAULT NULL,
  `action` varchar(32) NOT NULL,
  `outcome` varchar(32) NOT NULL,
  `confidence` int(11) NOT NULL DEFAULT 0,
  `context` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`context`)),
  `reviewed_by` int(11) DEFAULT NULL,
  `reviewed_at` datetime DEFAULT NULL,
  `review_decision` varchar(32) DEFAULT NULL,
  `review_note` varchar(500) DEFAULT NULL,
  `created_at` datetime DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `idx_sync_applicant` (`applicant_id`),
  KEY `idx_sync_action` (`action`,`created_at`),
  KEY `idx_sync_outcome` (`outcome`,`created_at`),
  KEY `idx_sync_pending_review` (`reviewed_by`,`reviewed_at`),
  KEY `idx_sync_confidence` (`confidence`),
  CONSTRAINT `sync_audit_log_ibfk_2` FOREIGN KEY (`reviewed_by`) REFERENCES `users` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `user_accounts` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `person_id` int(11) DEFAULT NULL,
  `username` varchar(50) DEFAULT NULL,
  `email` varchar(254) DEFAULT NULL,
  `display_name` varchar(100) DEFAULT NULL,
  `mobile` char(11) NOT NULL,
  `password` varchar(255) NOT NULL,
  `avatar_document_id` int(11) DEFAULT NULL,
  `failed_login_count` int(11) NOT NULL DEFAULT 0,
  `locked_until` datetime DEFAULT NULL,
  `last_login_at` datetime DEFAULT NULL,
  `is_active` tinyint(1) NOT NULL DEFAULT 1,
  `created_at` datetime DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `mobile` (`mobile`),
  UNIQUE KEY `username` (`username`),
  UNIQUE KEY `uq_user_accounts_person` (`person_id`),
  KEY `avatar_document_id` (`avatar_document_id`),
  KEY `idx_user_accounts_mobile` (`mobile`),
  KEY `idx_user_accounts_email` (`email`),
  CONSTRAINT `user_accounts_ibfk_1` FOREIGN KEY (`person_id`) REFERENCES `persons` (`id`) ON DELETE CASCADE,
  CONSTRAINT `user_accounts_ibfk_2` FOREIGN KEY (`avatar_document_id`) REFERENCES `documents` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `user_notifications` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `user_account_id` int(11) DEFAULT NULL,
  `applicant_id` int(11) DEFAULT NULL,
  `type` varchar(50) NOT NULL,
  `title` varchar(200) NOT NULL,
  `body` text DEFAULT NULL,
  `is_read` tinyint(1) NOT NULL DEFAULT 0,
  `created_at` datetime DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `applicant_id` (`applicant_id`),
  KEY `idx_notif_user` (`user_account_id`),
  KEY `idx_notif_unread` (`user_account_id`,`is_read`),
  KEY `idx_notif_type` (`type`,`created_at`),
  CONSTRAINT `user_notifications_ibfk_1` FOREIGN KEY (`user_account_id`) REFERENCES `user_accounts` (`id`) ON DELETE CASCADE,
  CONSTRAINT `user_notifications_ibfk_2` FOREIGN KEY (`applicant_id`) REFERENCES `applicants` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `user_sms_entries` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `applicant_id` int(11) NOT NULL,
  `sms_template_id` int(11) NOT NULL,
  `sms_code` varchar(50) DEFAULT NULL,
  `sms_text` text DEFAULT NULL,
  `received_at` date DEFAULT NULL,
  `status` varchar(32) NOT NULL DEFAULT 'در انتظار',
  `applied_status` tinyint(1) NOT NULL DEFAULT 0,
  `reviewed_by` int(11) DEFAULT NULL,
  `reviewed_at` datetime DEFAULT NULL,
  `reject_reason` varchar(255) DEFAULT NULL,
  `created_at` datetime DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `sms_template_id` (`sms_template_id`),
  KEY `reviewed_by` (`reviewed_by`),
  KEY `idx_sms_status` (`status`),
  KEY `idx_sms_applicant` (`applicant_id`),
  CONSTRAINT `user_sms_entries_ibfk_1` FOREIGN KEY (`applicant_id`) REFERENCES `applicants` (`id`) ON DELETE CASCADE,
  CONSTRAINT `user_sms_entries_ibfk_2` FOREIGN KEY (`sms_template_id`) REFERENCES `sms_templates` (`id`) ON DELETE CASCADE,
  CONSTRAINT `user_sms_entries_ibfk_3` FOREIGN KEY (`reviewed_by`) REFERENCES `users` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `users` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `username` varchar(50) NOT NULL,
  `password` varchar(255) NOT NULL,
  `display_name` varchar(100) DEFAULT NULL,
  `role` varchar(50) NOT NULL DEFAULT 'admin',
  `created_at` datetime DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `username` (`username`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `wizard_steps` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `view_key` varchar(64) NOT NULL,
  `title` varchar(150) NOT NULL,
  `service_type_id` int(11) DEFAULT NULL,
  `is_system` tinyint(1) NOT NULL DEFAULT 0,
  `is_active` tinyint(1) NOT NULL DEFAULT 1,
  `sort_order` int(11) NOT NULL DEFAULT 0,
  `icon` varchar(50) DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `view_key` (`view_key`),
  KEY `service_type_id` (`service_type_id`),
  CONSTRAINT `wizard_steps_ibfk_1` FOREIGN KEY (`service_type_id`) REFERENCES `service_types` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
